return [
  { json: { feed: 'Slow Living Collective', url: 'https://theslowlivingcollective.substack.com/feed' } },
  { json: { feed: 'Google News (EN)', url: 'https://news.google.com/rss/search?q=slow+living&hl=en&gl=US&ceid=US:en' } }
];

function guessFeed(link) {
  const u = String(link);
  if (u.includes('substack.com')) return 'Slow Living Collective';
  if (u.includes('news.google.com')) return 'Google News (EN)';
  return 'Diğer';
}

function stripHtml(html) {
  return String(html || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const WEEK_MS = 7 * 24 * 60 * 60 * 1000;
const cutoff = Date.now() - WEEK_MS;

function pubMs(j) {
  const raw = j.pubDate || j.isoDate || '';
  const t = new Date(raw).getTime();
  return Number.isNaN(t) ? null : t;
}

const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const link = (j.link || j.guid || '').toString();
  if (!link || seen.has(link)) continue;
  const ms = pubMs(j);
  if (ms == null || ms < cutoff) continue;
  seen.add(link);

  const desc =
    j.content ||
    j['content:encoded'] ||
    j.description ||
    j.contentSnippet ||
    j.summary ||
    '';
  let snippet = stripHtml(desc);
  if (!snippet) snippet = stripHtml(String(j.title || ''));
  if (snippet.length > 2800) snippet = snippet.slice(0, 2800) + '…';

  out.push({
    json: {
      feed: guessFeed(link),
      title: j.title || '(başlıksız)',
      link,
      pubDate: j.pubDate || j.isoDate || '',
      snippet,
    },
  });
}

if (!out.length) {
  return [{ json: { emptyWeek: true } }];
}
return out;

const first = $input.first().json;
if (first.emptyWeek === true) {
  return [{ json: { emptyWeek: true, hasArticles: false } }];
}

const articles = $input.all().map((i) => ({
  link: i.json.link,
  title: i.json.title,
  feed: i.json.feed,
  snippet: i.json.snippet || '',
}));

const userPrompt =
  'Görev: Aşağıdaki haber öğelerinin her biri için 2-4 cümlelik akıcı Türkçe özet yaz. Çıktı YALNIZCA tek bir JSON nesnesi olsun (markdown veya kod çiti yok, ek açıklama yok). Şema: {"summaries":[{"link":"<girdideki URL ile birebir aynı>","summary":"<Türkçe özet metni>"}]} . Türkçe harfleri doğru kullan (ş, ğ, ü, ö, ç, ı, İ vb.). Her link girdide tam olarak bir kez yer almalı.\n\nVERİ (JSON):\n' +
  JSON.stringify(articles);

return [{ json: { hasArticles: true, userPrompt, articlesForApply: articles } }];

const deduped = $('Dedupe by link').all();
const firstIn = $input.first().json;

function geminiResponseText(j) {
  const parts = j.content?.parts;
  if (Array.isArray(parts)) {
    const s = parts.map((p) => p.text).filter(Boolean).join('');
    if (s) return s;
  }
  if (typeof j.mergedResponse === 'string' && j.mergedResponse) return j.mergedResponse;
  return '';
}

let text = typeof firstIn.text === 'string' ? firstIn.text.trim() : '';
if (!text) text = geminiResponseText(firstIn);
if (!text) {
  text =
    firstIn.body?.choices?.[0]?.message?.content ||
    firstIn.choices?.[0]?.message?.content ||
    firstIn.data?.[0]?.message?.content ||
    firstIn.message?.content ||
    '';
}

function extractJson(s) {
  const t = String(s).trim();
  const start = t.indexOf('{');
  const end = t.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) throw new Error('no_json');
  return JSON.parse(t.slice(start, end + 1));
}

let summaries = [];
try {
  const parsed = extractJson(text);
  summaries = Array.isArray(parsed.summaries) ? parsed.summaries : [];
} catch (e) {
  summaries = [];
}

function decodeSummaryB64(x) {
  if (typeof Buffer === 'undefined') return '';
  const b64raw = (x.summary_b64 || x.summaryB64 || '').toString().replace(/\s/g, '');
  if (!b64raw) return '';
  let b64 = b64raw.replace(/-/g, '+').replace(/_/g, '/');
  const m = b64.length % 4;
  if (m === 1) return '';
  if (m) b64 += '='.repeat(4 - m);
  try {
    const dec = Buffer.from(b64, 'base64').toString('utf8');
    return dec || '';
  } catch (e) {
    return '';
  }
}

function fixLatin1MisreadUtf8(s) {
  if (!s || typeof Buffer === 'undefined') return s;
  try {
    const t = Buffer.from(s, 'latin1').toString('utf8');
    const cjk = /[\u4e00-\u9fff]/.test(t);
    const tr = /[şğıöüçıŞĞİÖÜÇ]/.test(t);
    if (tr && !cjk) return t;
  } catch (e2) {}
  return s;
}

function pickSummary(x) {
  const fromB64 = decodeSummaryB64(x);
  if (fromB64) return fromB64;
  const plain = String(x.summary || '').trim();
  return plain ? fixLatin1MisreadUtf8(plain) : '';
}

const byLink = new Map(summaries.map((x) => [String(x.link || ''), pickSummary(x)]));

return deduped.map((item) => {
  const link = String(item.json.link || '');
  const sum = byLink.get(link) || '';
  return {
    json: {
      ...item.json,
      summaryTr:
        sum ||
        'Özet üretilemedi; yine de başlık ve RSS alıntısından genel fikir edinebilirsiniz.',
    },
  };
});

function escapeHtml(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function formatDate(raw) {
  const s = String(raw || '').trim();
  if (!s) return '—';
  const d = new Date(s);
  if (Number.isNaN(d.getTime())) return escapeHtml(s);
  return d.toLocaleString('tr-TR', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
}

const items = $input.all();
const first = items[0]?.json;

if (first?.emptyWeek === true) {
  const generated = new Date().toLocaleString('tr-TR', {
    day: '2-digit',
    month: 'long',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
  const html =
    '\ufeff<!DOCTYPE html><html lang="tr"><head><meta http-equiv="Content-Type" content="text/html; charset=UTF-8"><meta charset="utf-8"></head><body style="margin:0;padding:24px;background:#f4f4f5;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;">' +
    '<table role="presentation" width="100%"><tr><td align="center">' +
    '<table role="presentation" style="max-width:560px;background:#fff;border-radius:12px;padding:28px;text-align:left;">' +
    '<tr><td><p style="margin:0 0 12px;font-size:13px;color:#1a4d3a;font-weight:600;">Slow Living Radar</p>' +
    '<h1 style="margin:0 0 10px;font-size:20px;color:#111;">Bu hafta özetlenecek yeni içerik yok</h1>' +
    '<p style="margin:0;font-size:14px;line-height:1.55;color:#444;">Son <strong>7 gün</strong> içinde yayınlanmış ve RSS’te geçerli tarih bilgisi olan madde bulunamadı. Bir sonraki haftalık çalıştırmada tekrar denenecek.</p>' +
    '<p style="margin:16px 0 0;font-size:12px;color:#888;">' +
    escapeHtml(generated) +
    '</p></td></tr></table></td></tr></table></body></html>';
  return [{ json: { html, itemCount: 0 } }];
}

const rows = items
  .map((i, idx) => {
    const r = i.json;
    const title = escapeHtml(r.title || '(başlıksız)');
    const feed = escapeHtml(r.feed || '');
    const link = String(r.link || '');
    const href = escapeHtml(link);
    const when = formatDate(r.pubDate);
    const sum = escapeHtml(r.summaryTr || '');
    const num = idx + 1;
    return (
      '<tr>' +
      '<td style="padding:12px 10px;border-bottom:1px solid #e8e8e8;color:#666;font-size:13px;width:36px;vertical-align:top;">' +
      num +
      '</td>' +
      '<td style="padding:12px 10px;border-bottom:1px solid #e8e8e8;font-size:13px;color:#333;font-weight:600;vertical-align:top;">' +
      feed +
      '</td>' +
      '<td style="padding:12px 10px;border-bottom:1px solid #e8e8e8;font-size:15px;line-height:1.45;color:#111;vertical-align:top;">' +
      title +
      '</td>' +
      '<td style="padding:12px 10px;border-bottom:1px solid #e8e8e8;font-size:13px;white-space:nowrap;vertical-align:top;">' +
      '<a href="' +
      href +
      '" style="color:#0b57d0;text-decoration:none;font-weight:600;">Oku →</a>' +
      '</td>' +
      '<td style="padding:12px 10px;border-bottom:1px solid #e8e8e8;font-size:12px;color:#666;vertical-align:top;">' +
      when +
      '</td>' +
      '</tr>' +
      '<tr><td colspan="5" style="padding:4px 12px 18px 44px;border-bottom:1px solid #ddd;font-size:13px;line-height:1.55;color:#333;background:#fafafa;">' +
      '<strong style="color:#1a4d3a;">Özet</strong><br>' +
      sum +
      '</td></tr>'
    );
  })
  .join('\n');

const count = items.length;
const generated = new Date().toLocaleString('tr-TR', {
  day: '2-digit',
  month: 'long',
  year: 'numeric',
  hour: '2-digit',
  minute: '2-digit',
});

const html =
  '\ufeff<!DOCTYPE html>' +
  '<html lang="tr">' +
  '<head><meta http-equiv="Content-Type" content="text/html; charset=UTF-8"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">' +
  '<title>Haftalık slow living özeti</title></head>' +
  '<body style="margin:0;padding:0;background:#f4f4f5;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;">' +
  '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#f4f4f5;padding:24px 12px;">' +
  '<tr><td align="center">' +
  '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="max-width:640px;background:#ffffff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.06);">' +
  '<tr><td style="padding:22px 24px;background:#1a4d3a;color:#fff;">' +
  '<p style="margin:0;font-size:12px;opacity:0.9;letter-spacing:0.04em;text-transform:uppercase;">Slow Living Radar</p>' +
  '<h1 style="margin:6px 0 0;font-size:22px;font-weight:600;line-height:1.25;">Haftalık sakin yaşam özeti</h1>' +
  '<p style="margin:8px 0 0;font-size:13px;opacity:0.92;">' +
  generated +
  ' · son <strong>7 gün</strong>de yayınlanan <strong>' +
  count +
  '</strong> içerik · Türkçe özetler Google Vertex AI (Gemini) ile üretildi</p>' +
  '</td></tr>' +
  '<tr><td style="padding:18px 24px 8px;">' +
  '<p style="margin:0 0 14px;font-size:14px;color:#444;line-height:1.5;">Merhaba,<br>' +
  'Aşağıdaki liste yalnızca <strong>son 7 gün</strong> içinde RSS’te görünen yayınları içerir. Her satırın altında, başlık ve akıştaki kısa alıntıya dayanan bir <strong>Türkçe özet</strong> bulunur; ayrıntı için bağlantıyı kullanabilirsiniz.</p>' +
  '</td></tr>' +
  '<tr><td style="padding:0 8px 20px;">' +
  '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="border-collapse:collapse;">' +
  '<tr>' +
  '<th align="left" style="padding:10px;font-size:11px;text-transform:uppercase;letter-spacing:0.06em;color:#888;border-bottom:2px solid #e0e0e0;">#</th>' +
  '<th align="left" style="padding:10px;font-size:11px;text-transform:uppercase;letter-spacing:0.06em;color:#888;border-bottom:2px solid #e0e0e0;">Kaynak</th>' +
  '<th align="left" style="padding:10px;font-size:11px;text-transform:uppercase;letter-spacing:0.06em;color:#888;border-bottom:2px solid #e0e0e0;">Başlık</th>' +
  '<th align="left" style="padding:10px;font-size:11px;text-transform:uppercase;letter-spacing:0.06em;color:#888;border-bottom:2px solid #e0e0e0;">Bağlantı</th>' +
  '<th align="left" style="padding:10px;font-size:11px;text-transform:uppercase;letter-spacing:0.06em;color:#888;border-bottom:2px solid #e0e0e0;">Yayın</th>' +
  '</tr>' +
  rows +
  '</table></td></tr>' +
  '<tr><td style="padding:16px 24px 22px;background:#fafafa;border-top:1px solid #eee;">' +
  '<p style="margin:0;font-size:12px;color:#777;line-height:1.5;">Kaynaklar: Slow Living Collective (Substack), Google News RSS. Zen Habits kaldırıldı (eski tarihli içerik). Zamanlama: her Pazartesi 08:00 (n8n workflow aktifken).</p>' +
  '</td></tr></table></td></tr></table></body></html>';

return [{ json: { html, itemCount: count } }];
